func (r *GormWebhookRepository) Update(ctx context.Context, in *webhookpbv1.Webhook, paths []string) (*webhookpbv1.Webhook, error) {
	ids, err := repox.SplitName(in.GetName(), "webhooks")
	if err != nil {
		return nil, err
	}
	id := ids[len(ids)-1]
	err = r.DB.Transaction(func(tx *gorm.DB) error {
		var existing webhook.Webhook
		if err := tx.WithContext(ctx).First(&existing, "id = ?", id).Error; err != nil {
			return err
		}
		if in.GetEtag() != "" && existing.Etag != nil && *existing.Etag != in.GetEtag() {
			return repox.ErrConflict
		}
		existingPB := webhook.WebhookToProto(&existing)
		merged := proto.Clone(existingPB).(*webhookpbv1.Webhook)
		applyWebhookMask(merged, in, paths)
		if h := r.Hooks.BeforeUpdate; h != nil {
			if err := h(ctx, existingPB, merged, paths); err != nil {
				return err
			}
		}
		next := webhook.WebhookFromProto(merged)
		_ = next
		existing.Name = next.Name
		existing.DisplayName = next.DisplayName
		existing.URI = next.URI
		existing.EventTypes = next.EventTypes
		existing.OrganizationalUnit = next.OrganizationalUnit
		existing.Etag = repox.Ptr(repox.NewULID())
		return webhook.NewWebhookStore(tx).Update(ctx, &existing)
	})
	if err != nil {
		return nil, repox.MapGormErr(err)
	}
	return r.get(ctx, id)
}

// UpdateOutputOnly persists the server-owned fields of in that paths names, in
// one transaction guarded by in.Etag.
func (r *GormWebhookRepository) UpdateOutputOnly(ctx context.Context, in *webhookpbv1.Webhook, paths []string) (*webhookpbv1.Webhook, error) {
	ids, err := repox.SplitName(in.GetName(), "webhooks")
	if err != nil {
		return nil, err
	}
	err = r.DB.Transaction(func(tx *gorm.DB) error { return r.updateOutputOnlyTx(ctx, tx, in, paths) })
	if err != nil {
		return nil, repox.MapGormErr(err)
	}
	return r.get(ctx, ids[len(ids)-1])
}

// updateOutputOnlyTx is UpdateOutputOnly's write inside tx, which a Batch
// shares with other writes.
func (r *GormWebhookRepository) updateOutputOnlyTx(ctx context.Context, tx *gorm.DB, in *webhookpbv1.Webhook, paths []string) error {
	if len(paths) == 0 {
		return fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument)
	}
	ids, err := repox.SplitName(in.GetName(), "webhooks")
	if err != nil {
		return err
	}
	id := ids[len(ids)-1]
	{
		var existing webhook.Webhook
		if err := tx.WithContext(ctx).First(&existing, "id = ?", id).Error; err != nil {
			return err
		}
		if in.GetEtag() != "" && existing.Etag != nil && *existing.Etag != in.GetEtag() {
			return repox.ErrConflict
		}
		next := webhook.WebhookFromProto(in)
		if repox.InMask(paths, "state") {
			existing.State = next.State
		}
		if repox.InMask(paths, "secret") {
			existing.Secret = next.Secret
		}
		if repox.InMask(paths, "previous_secret") {
			existing.PreviousSecret = next.PreviousSecret
		}
		if repox.InMask(paths, "rotate_time") {
			existing.RotateTime = next.RotateTime
		}
		existing.Etag = repox.Ptr(repox.NewULID())
		return webhook.NewWebhookStore(tx).Update(ctx, &existing)
	}
}

// newRow builds the row a Batch inserts for in, and the
// name the record will have: the same resolution Create applies.
func (r *GormWebhookRepository) newRow(in *webhookpbv1.Webhook) (*webhook.Webhook, string, error) {
	id := repox.NewULID()
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "webhooks")
		if err != nil {
			return nil, "", err
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*webhookpbv1.Webhook)
	in.Name = FormatWebhookName(id)
	m := webhook.WebhookFromProto(in)
	m.ID = id
	m.Name = in.GetName()
	m.Etag = repox.Ptr(repox.NewULID())
	return m, in.GetName(), nil
}

// Delete removes the record addressed by its resource name.
func (r *GormWebhookRepository) Delete(ctx context.Context, name string) error {
	ids, err := repox.SplitName(name, "webhooks")
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id := ids[len(ids)-1]
	var existing webhook.Webhook
	if err := r.DB.WithContext(ctx).First(&existing, "id = ?", id).Error; err != nil {
		return repox.MapGormErr(err)
	}
	return repox.MapGormErr(webhook.NewWebhookStore(r.DB).DeleteByID(ctx, id))
}

// Compile-time proof the adapter satisfies the interface.
var _ WebhookRepository = (*GormWebhookRepository)(nil)

// gormBatch is Batch on GORM: queued writes run in one transaction on Commit.
type gormBatch struct {
	db  *gorm.DB
	ops []func(ctx context.Context, tx *gorm.DB) error
	err error // the first queueing error; Commit returns it and writes nothing
}

// Commit runs every queued write in one transaction: all land or none do.
func (b *gormBatch) Commit(ctx context.Context) error {
	if b.err != nil {
		return b.err
	}
	if len(b.ops) == 0 {
		return nil
	}
	return repox.MapGormErr(b.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		for _, op := range b.ops {
			if err := op(ctx, tx); err != nil {
				return err
			}
		}
		return nil
	}))
}

func (b *gormBatch) fail(err error) {
	if b.err == nil {
		b.err = err
	}
}

// CreateDelivery queues a create and returns the name the record will have.
func (b *gormBatch) CreateDelivery(parent string, in *webhookpbv1.Delivery) (string, error) {
	m, name, err := (&GormDeliveryRepository{DB: b.db}).newRow(parent, in)
	if err != nil {
		return "", err
	}
	b.ops = append(b.ops, func(ctx context.Context, tx *gorm.DB) error {
		return webhook.NewDeliveryStore(tx).Create(ctx, m)
	})
	return name, nil
}

// UpdateDeliveryOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards it.
func (b *gormBatch) UpdateDeliveryOutputOnly(in *webhookpbv1.Delivery, paths []string) {
	r := &GormDeliveryRepository{DB: b.db}
	b.ops = append(b.ops, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateOutputOnlyTx(ctx, tx, in, paths)
	})
}

// DeleteDelivery queues the record's removal for good. A record already
// gone is not an error: two batches clearing the same row must not fail each
// other.
func (b *gormBatch) DeleteDelivery(name string) {
	ids, err := repox.SplitName(name, "webhooks", "deliveries")
	if err != nil {
		b.fail(err)
		return
	}
	id := ids[len(ids)-1]
	b.ops = append(b.ops, func(ctx context.Context, tx *gorm.DB) error {
		return tx.WithContext(ctx).Delete(&webhook.Delivery{}, "id = ?", id).Error
	})
}

